    var fixedToENU_wetness = mat3x3<f32>(modelView[0][0], modelView[1][0], modelView[2][0], modelView[0][1], modelView[1][1], modelView[2][1], modelView[0][2], modelView[1][2], modelView[2][2]);
    var normalWS_wetness = normalize(fixedToENU_wetness * n);
