    var baseColor = baseColorWithAlpha.rgb;
    var roughness = Material.uMetallicRoughnessIntensityScale.y;
    var metalness = Material.uMetallicRoughnessIntensityScale.x;
    var ambientOcclusion = 1.0;
    var emissiveFactor = Material.uEmissiveFactor;

    // TODO
// #ifdef PBR_THEME
//     var pbrIndex = int(vPBRIndex);
//     if(vPBRIndex < 0.0f)
