    var val_sw : vec4<f32> = textureSample(uGlobalNormalTexture, uGlobalNormalTextureSampler, tex_sw.xy);
    val_sw.x = ((val_sw.xyz * 2.0 ) - 1.0).x;
    val_sw.y = ((val_sw.xyz * 2.0 ) - 1.0).y;
    val_sw.z = ((val_sw.xyz * 2.0 ) - 1.0).z;
